    static GATE: OnceLock<Arc<tokio::sync::Mutex<tokio::time::Instant>>> = OnceLock::new();
    Arc::clone(GATE.get_or_init(|| Arc::new(tokio::sync::Mutex::new(tokio::time::Instant::now()))))
}

impl MusicBrainzProvider {
