Implementation:
```rust
    let mut counts = SelectionCounts { releases_examined: releases.len(), ..Default::default() };
    let excluded: std::collections::BTreeSet<String> = exclude_artists
        .iter().map(|name| normalize_catalog_key(name)).filter(|key| !key.is_empty()).collect();

    // Group release groups by the artist credit they were released under, and
    // remember each release group's earliest date for the final ordering.
    let mut groups: BTreeMap<String, (String, Vec<ReleaseGroup>)> = BTreeMap::new();
    let mut dates: BTreeMap<String, Option<PartialDate>> = BTreeMap::new();

    for release in releases {
        let credit_key = normalize_catalog_key(&release.artist_credit);
        if credit_key.is_empty() || excluded.contains(&credit_key) {
            counts.excluded_credits += 1;
            continue;
        }
        if !release_allowed(&release.release_group, allowed) {
            counts.not_wanted_type += 1;
            continue;
        }
        let date = release.release_group.first_release_date.as_deref().and_then(crate::discography::parse_partial_date);
        if let Some(bound) = since {
            match date {
                Some(date) if date >= bound => {}
                Some(_) => { counts.since_skipped += 1; continue; }
                None => { counts.undated_skipped += 1; continue; }
            }
        }
        dates.entry(release.release_group.id.clone())
            .and_modify(|slot| {
                if let (Some(existing), Some(candidate)) = (*slot, date) {
                    if candidate < existing { *slot = Some(candidate); }
                } else if slot.is_none() { *slot = date; }
            })
            .or_insert(date);
        let entry = groups.entry(credit_key).or_insert_with(|| (release.artist_credit.clone(), Vec::new()));
        entry.1.push(release.release_group.clone());
    }

    // select_albums applies the type filter again, bundle decomposition and the
    // album-identity collapse, so each credit group yields the same targets the
    // artist sweep would.
    let mut merged: Vec<(String, Option<PartialDate>, LabelTarget)> = Vec::new();
    let mut seen: std::collections::BTreeSet<(String, String)> = std::collections::BTreeSet::new();
    for (credit_key, (credit, groups)) in groups {
        for target in select_albums(&groups, allowed, &credit) {
            let identity = crate::search::album_identity_key(&target.title, &credit);
            if !seen.insert((credit_key.clone(), identity)) { continue; }
            let date = dates.get(&target.release_group_id).copied().flatten();
            merged.push((credit_key.clone(), date, LabelTarget { artist: credit.clone(), target }));
        }
    }
    merged.sort_by(|a, b| {
        a.0.cmp(&b.0)
            .then_with(|| match (a.1, b.1) {
                (Some(a_date), Some(b_date)) => a_date.cmp(&b_date),
                (Some(_), None) => std::cmp::Ordering::Less,
                (None, Some(_)) => std::cmp::Ordering::Greater,
                (None, None) => std::cmp::Ordering::Equal,
            })
            .then_with(|| normalize_catalog_key(&a.2.target.title).cmp(&normalize_catalog_key(&b.2.target.title)))
            .then_with(|| a.2.target.release_group_id.cmp(&b.2.target.release_group_id))
    });
    counts.eligible = merged.len();
    LabelTargets { targets: merged.into_iter().map(|(_, _, target)| target).collect(), counts }
