/// The MBID pinned for this input, when one is configured.
///
/// The lookup is by the value the operator gave, whatever its shape, so a pin
/// wins over the input's own shape: a label literally named like a UUID is read
/// as an ID by [`LabelInput::parse`], and the pin keyed by that same text is what
/// rescues it. An unrelated pin never matches an ID input, because the key would
/// be a different string.
pub fn pinned_mbid<'a>(pins: &'a BTreeMap<String, String>, input: &LabelInput) -> Option<&'a str> {
    let key = identifier_pin_key(input.display());
    pins.iter()
        .find(|(pinned, _)| identifier_pin_key(pinned) == key)
        .map(|(_, mbid)| mbid.as_str())
}

