pub fn label_targets(
    releases: &[LabelRelease],
    allowed: &[DiscographyReleaseType],
    since: Option<PartialDate>,
    exclude_artists: &[String],
) -> LabelTargets {
    let mut counts = SelectionCounts { releases_examined: releases.len(), ..Default::default() };
    let excluded: BTreeSet<String> = ...;

    // Group by credit, and remember each release group's earliest date.
    // Every non-excluded release group is pushed, whatever its type or date:
    // `select_albums` builds its bundle-visibility set from the groups it is
    // given, and the artist sweep builds that set before the release-type filter
    // runs, so pre-filtering here would let a bundle part disappear and the bundle
    // be selected as a plain album.
    let mut groups: BTreeMap<String, (String, Vec<ReleaseGroup>)> = BTreeMap::new();
    let mut dates: BTreeMap<String, Option<PartialDate>> = BTreeMap::new();
    for release in releases {
        let credit_key = normalize_catalog_key(&release.artist_credit);
        if credit_key.is_empty() || excluded.contains(&credit_key) {
            counts.excluded_credits += 1;
            continue;
        }
        // Counters stay per release and reflect the filters the operator asked for,
        // even though the filters are applied to the selected targets below.
        if !release_allowed(&release.release_group, allowed) {
            counts.not_wanted_type += 1;
        }
        let date = ...;
        if let Some(bound) = since {
            match date {
                Some(date) if date >= bound => {}
                Some(_) => counts.since_skipped += 1,
                None => counts.undated_skipped += 1,
            }
        }
        dates.entry(...).and_modify(...).or_insert(date);
        groups.entry(credit_key).or_insert_with(...).1.push(release.release_group.clone());
    }

    let mut merged: Vec<(String, Option<PartialDate>, LabelTarget)> = Vec::new();
    // One album is one target: the within-credit identity rule, plus the
    // release-group id so the same release group listed under a different credit
    // cannot be downloaded twice.
    let mut seen_identities: BTreeSet<(String, String)> = BTreeSet::new();
    let mut seen_groups: BTreeSet<String> = BTreeSet::new();
    for (credit_key, (credit, groups)) in groups {
        for target in select_albums(&groups, allowed, &credit) {
            let date = dates.get(&target.release_group_id).copied().flatten();
            if let Some(bound) = since {
                // select_albums does not know the bound; a target whose own date
                // cannot satisfy it is dropped here.
                match date {
                    Some(date) if date >= bound => {}
                    _ => continue,
                }
            }
            let identity = album_identity_key(&target.title, &credit);
            if !seen_identities.insert((credit_key.clone(), identity))
                || !seen_groups.insert(target.release_group_id.clone()) {
                continue;
            }
            merged.push((credit_key.clone(), date, LabelTarget { artist: credit.clone(), target }));
        }
    }
    ... sort ... counts.eligible = merged.len();
