```rust
/// Values listed in one notice before it is truncated.
const MAX_LISTED_VALUES: usize = 10;

/// Join values for a notice, truncating like the artist sweep's summary does.
fn listed(values: &[String]) -> String {
    if values.len() <= MAX_LISTED_VALUES {
        return values.join(", ");
    }
    let shown = values[..MAX_LISTED_VALUES].join(", ");
    format!("{shown}, and {} more", values.len() - MAX_LISTED_VALUES)
}
