2. musicbrainz: ArtistCreditWire fallback:
```rust
#[derive(Debug, Deserialize)]
struct ArtistCreditWire {
    #[serde(default)]
    name: String,
    #[serde(default)]
    joinphrase: Option<String>,
    /// The credited artist entity. Its `name` is the fallback when the credit
    /// carries no `name` of its own, which MusicBrainz does for a credit that simply
    /// repeats the artist.
    #[serde(default)]
    artist: Option<ArtistRefWire>,
}
#[derive(Debug, Deserialize)]
struct ArtistRefWire { #[serde(default)] name: String }

fn credit_string(credits: &[ArtistCreditWire]) -> String {
    let mut credit = String::new();
    for part in credits {
        let name = if part.name.trim().is_empty() {
            part.artist.as_ref().map(|a| a.name.trim()).unwrap_or("")
        } else { part.name.trim() };
        credit.push_str(name);
        if let Some(join) = part.joinphrase.as_deref() { credit.push_str(join); }
    }
    credit.trim().to_string()
}
